/** Safe synthetic current-manifest publishers; not a source-system connector. */
import {mkdir,writeFile} from 'node:fs/promises';
import path from 'node:path';
import {sha} from '../../scripts/lib/tendermatch-input-manifest.mjs';
import {SOURCE_SCHEMA,manifestCapture} from '../../scripts/lib/tendermatch-stage10-source.mjs';
export const id=n=>`00000000-0000-0000-0000-${String(n).padStart(12,'0')}`;
export const TENANT='stage10-synthetic-local';
export function supplier(n=1,{terms='Electrical transformers and steel parts',capacity=true}={}){
  const evidence=[['classification','GOODS'],['product_families',terms],...(capacity?[['capacity','Employees: 120 employees'],['geographic_markets','Central Asia']]:[])].map(([field,value],i)=>({canonical_entity_id:id(n),profile_version_id:id(n+5000),claim_id:id(n*10000+i),external_claim_id:null,field,source_field:field,display_value:value,status:'STATED_UNVERIFIED',value_class:'SOURCE',source_record_id:id(n*20000+i),source_system:'SYNTHETIC',retrieved_at:'2026-09-07T00:00:00Z',source_artifact_id:id(n*30000+i),artifact_available:true,artifact_status:'SAVED',artifact_sha256:sha([n,i]),artifact_limitation:'',formula_role:'SUPPORTING_ONLY'}));
  return {kind:'supplier',id:id(n),sourceVersion:'synthetic/1',baseContentHash:sha(evidence),provenance:{profile_id:id(n+5000)},profile:{canonical_entity_id:id(n),profile_version_id:id(n+5000),display_name:'Synthetic company '+n,legal_name:'Synthetic company '+n,country_code:'CN',entity_type_code:'company',classification:'GOODS',classification_value_class:'SOURCE',classification_claim_ids:[evidence[0].claim_id],profile_state:'PINNED',readiness_status:'usable_with_limitations',readiness_contract_version:'synthetic',verification_status:'under_review',evidence_count:evidence.length},evidence};
}
export function tender(n=1000,{status='OPEN',deleted=false,category='GOODS',title='Electrical transformer procurement'}={}){return {kind:'tender',id:id(n),sourceVersion:'synthetic/1',baseContentHash:sha([n,title,status,deleted]),provenance:{deleted,status,source_id:id(900000)},tender:{title,description:'Synthetic notice-level procurement only.',descriptionLength:40,procurementType:category,status,reference:'SYN-'+n,budgetAmount:null,budgetCurrency:null,budgetUsd:null,deadlineAt:null,publishedAt:null,sourceTimezone:null,deadlineSourceText:null},lookups:{country:{id:id(900001),name:'Uzbekistan',isoAlpha2:'UZ',isoAlpha3:'UZB'},tags:[]}};}
export function manifestSet(inputs,{tenantId=TENANT,unlisted=[],contracts={}}={}){return Object.fromEntries(['supplier','tender'].map(kind=>[kind,{schema:SOURCE_SCHEMA,tenantId,kind,contractVersion:contracts[kind]??'synthetic-safe-source/1',members:inputs.filter(i=>i.kind===kind).map(input=>({id:input.id,digest:sha(input),file:sha(input)+'.json',deleted:input.kind==='supplier'?false:input.provenance.deleted,...(kind==='supplier'?{listed:!unlisted.includes(input.id)}:{status:input.tender.status})}))}]));}
export function memorySource(initial,options={}){let inputs=structuredClone(initial),opts=options,reads=0;const source={capture:async()=>manifestCapture(manifestSet(inputs,opts),opts.tenantId??TENANT),assertCurrentSync:capture=>{if(manifestCapture(manifestSet(inputs,opts),opts.tenantId??TENANT).sourceToken!==capture.sourceToken)throw Error('SOURCE_DRIFT');},assertCurrent:async capture=>{if((await source.capture()).sourceToken!==capture.sourceToken)throw Error('SOURCE_DRIFT');},read:async m=>{reads++;const body=inputs.find(i=>i.kind===m.kind&&i.id===m.id);if(!body||sha(body)!==m.digest)throw Error('SOURCE_RECORD_IDENTITY');return structuredClone(body);},replace:(next,nextOptions=opts)=>{inputs=structuredClone(next);opts=nextOptions;},reads:()=>reads};return source;}
export async function publishFiles(directory,inputs,options={}){await mkdir(directory,{recursive:true});const manifests=manifestSet(inputs,options),tenantId=options.tenantId??TENANT;for(const input of inputs)await writeFile(path.join(directory,sha(input)+'.json'),JSON.stringify(input));const pointer={schema:SOURCE_SCHEMA,tenantId};for(const kind of ['supplier','tender']){const digest=sha(manifests[kind]),file=kind+'-'+digest+'.json';await writeFile(path.join(directory,file),JSON.stringify(manifests[kind]));pointer[kind]={file,digest};}await writeFile(path.join(directory,'CURRENT.json'),JSON.stringify(pointer));}
